INSERT INTO questions_questionfeedback (id, question_id, user_id, category, comment, status, is_resolved, resolution_note, resolved_by_id, resolved_at, notified_user, created_at) VALUES (24, 9979, 57, 'discrepancy', 'Answer is in the option', 'new', false, '', NULL, NULL, false, '2026-07-23 13:45:11.728852+00:00'), (23, 2194, 57, 'wrong_answer', 'Correct answer is option a not b', 'new', false, '', NULL, NULL, false, '2026-07-23 13:34:21.620233+00:00'), (22, 2241, 25, 'wrong_answer', 'galat', 'new', false, '', NULL, NULL, false, '2026-07-20 11:23:19.760643+00:00'), (21, 6579, 25, 'wrong_answer', 'galat', 'new', false, '', NULL, NULL, false, '2026-07-19 12:50:37.741026+00:00'), (20, 6582, 1, 'wrong_answer', 'option 4', 'new', false, '', NULL, NULL, false, '2026-07-19 12:47:36.260028+00:00'), (19, 5830, 55, 'wrong_answer', 'Prevalence of neonatal hypothyroidism: This is the correct choice. The newborn thyroid is exceptionally vulnerable to a lack of iodine due to its accelerated intrinsic turnover rate. Fluctuations in environmental iodine levels reflect instantly in neonatal TSH spikes. A high prevalence acts as the most sensitive early clinical warning sign that an environment lacks the iodine required to protect against endemic brain damage. So option B.', 'new', false, '', NULL, NULL, false, '2026-07-18 16:19:00.269209+00:00'), (18, 6751, 55, 'typo', 'question spacing', 'new', false, '', NULL, NULL, false, '2026-07-18 16:10:54.877756+00:00'), (17, 5552, 55, 'typo', 'numbering', 'new', false, '', NULL, NULL, false, '2026-07-18 16:09:18.850803+00:00'), (16, 6750, 55, 'typo', 'option words are in the question', 'new', false, '', NULL, NULL, false, '2026-07-18 16:04:52.274214+00:00'), (15, 6750, 55, 'wrong_answer', 'Their ducts open at the junction of the anterior two-thirds and posterior one-third of the vaginal orifice (hymen), not between anterior one-third and posterior two-thirds. so answer is B.', 'new', false, '', NULL, NULL, false, '2026-07-18 16:04:15.765261+00:00'), (14, 5208, 55, 'typo', 'numbering', 'new', false, '', NULL, NULL, false, '2026-07-18 15:44:12.691244+00:00'), (12, 4484, 55, 'typo', 'numbering', 'new', false, '', NULL, NULL, false, '2026-07-18 15:36:58.867673+00:00'), (11, 5549, 55, 'typo', 'numbering', 'new', false, '', NULL, NULL, false, '2026-07-18 15:36:42.573019+00:00'), (9, 2026, 55, 'wrong_answer', 'Autosomal recessive trait of a mutation in the gene for UDP-glucuronyl transferase enzyme - This statement is correct. Gilbert Syndrome is indeed characterized by a mutation in the UDP-glucuronyltransferase 1A1 (UGT1A1) gene, which is inherited in an autosomal recessive pattern. so answer is C.', 'new', false, '', NULL, NULL, false, '2026-07-18 13:43:44.229000+00:00'), (8, 2017, 55, 'wrong_answer', 'Given these parameters, the most likely diagnosis is B. Myxedema. Myxedema, associated with hypothyroidism, can cause a transudative pleural effusion, which is characterized by low protein levels in the pleural fluid, as seen here (0.5 g/dL). The low pleural fluid protein level is key in differentiating transudative from exudative effusions.', 'new', false, '', NULL, NULL, false, '2026-07-18 07:32:52.273000+00:00'), (7, 2011, 55, 'wrong_answer', 'Answer is not ''Breathe, Ready, Aim, Fire, Hold'' as in A. It''s ''Ready, Breathe, Aim, Fire, Hold'' as in C.', 'new', false, '', NULL, NULL, false, '2026-07-18 07:16:39.498000+00:00'), (6, 2009, 55, 'wrong_answer', 'The correct statement is C: OS moves closer to the second sound S2 as the stenosis becomes more severe. As severe stenosis to higher LA pressure to earlier valve opening to S2-OS interval shortens.', 'new', false, '', NULL, NULL, false, '2026-07-18 07:03:53.060000+00:00'), (5, 6677, 55, 'wrong_answer', 'The pharmacologic effect of Warfarin is likely to Decrease (Option B) when antitubercular treatment (ATT) is started d/t Rifampicin is potent inducer of CYP450.', 'new', false, '', NULL, NULL, false, '2026-07-17 16:31:12.222000+00:00'), (4, 6678, 55, 'wrong_answer', 'Retrograde amnesia is not a component of Wernicke''s syndrome. Wernicke''s syndrome is characterized by the classic triad of ataxia ophthalmoplegia, and encephalopathy', 'new', false, '', NULL, NULL, false, '2026-07-17 16:29:56.267000+00:00'), (3, 5250, 31, 'wrong_answer', 'Answer is d', 'resolved', true, '', 1, '2026-07-17 08:17:41.293000+00:00', false, '2026-07-12 20:39:42.243000+00:00') ON CONFLICT (id) DO NOTHING;